<template>
  <section class="rating-card" aria-label="Đánh giá của học viên đối với khóa học">
    <header><div><h3>Đánh giá của học viên về khóa học</h3><p>Mức độ hài lòng và phản hồi để cải thiện chất lượng đào tạo.</p></div><Star :size="20"/></header>
    <div class="rating-note">Đánh giá khóa học · dữ liệu minh họa riêng, chưa kết nối dữ liệu thực.</div>
    <div class="rating-layout">
      <div class="rating-score"><strong>{{ metrics.average===null?'—':metrics.average.toFixed(1) }}<small>/5</small></strong><span class="rating-stars" :style="{ backgroundImage: `linear-gradient(to right, #b88723 ${((metrics.average || 0)/5)*100}%, var(--border-color) ${((metrics.average || 0)/5)*100}%)` }" aria-hidden="true">★★★★★</span><p>{{ metrics.count }} đánh giá hợp lệ</p></div>
      <div class="rating-distribution" aria-label="Phân bố số sao"><div v-for="bin in metrics.distribution" :key="bin.stars"><span>{{ bin.stars }} sao</span><div class="rating-track" aria-hidden="true"><i :style="{width:`${metrics.count?bin.count/metrics.count*100:0}%`}"></i></div><strong>{{ bin.count }}</strong></div></div>
      <div class="rating-stats"><div><span>Học viên hoàn thành đã đánh giá</span><strong>{{ metrics.responseRate===null?'—':`${Math.round(metrics.responseRate)}%` }}</strong><small>{{ metrics.count }} / {{ metrics.eligible }} lượt hoàn thành trong phạm vi</small></div><button :aria-pressed="onlyLow" @click="onlyLow=!onlyLow"><span>Phản hồi 1–2 sao</span><strong>{{ metrics.low }}</strong><small>{{ onlyLow?'Bấm để xem tất cả phản hồi':'Bấm để xem phản hồi cần chú ý' }}</small></button></div>
    </div>
    <div class="rating-courses" v-if="byCourse.length"><div class="rating-subheading"><h4>Đánh giá theo khóa học</h4><span>Điểm sao luôn đi kèm số lượt đánh giá</span></div><div class="rating-table-scroll" tabindex="0" role="region" aria-label="Bảng đánh giá theo khóa học"><table><thead><tr><th>Khóa học</th><th>Điểm sao /5</th><th>Đã đánh giá / hoàn thành</th><th>Tỷ lệ phản hồi</th><th>1–2 sao</th><th>Phản hồi</th></tr></thead><tbody><tr v-for="course in byCourse" :key="course.name"><td>{{ course.name }}</td><td>{{ course.average===null?'Chưa đánh giá':course.average.toFixed(1) }}</td><td>{{ course.count }} / {{ course.eligible }}</td><td>{{ course.responseRate===null?'—':`${Math.round(course.responseRate)}%` }}</td><td>{{ course.low }}</td><td><button class="rating-link" @click="courseFilter=course.name;onlyLow=false">Xem phản hồi</button></td></tr></tbody></table></div></div>
    <div class="rating-subheading"><h4>{{ onlyLow?'Phản hồi cần chú ý (1–2 sao)':'Phản hồi học viên' }}</h4><button v-if="courseFilter||onlyLow" class="rating-link" @click="courseFilter='';onlyLow=false">Xem tất cả</button></div>
    <p v-if="courseFilter" class="rating-scope">Khóa học: {{ courseFilter }}</p>
    <div class="rating-comments"><article v-for="review in visibleReviews.slice(0,limit)" :key="review.id"><div><strong>{{ learnerName(review.learnerId) }}</strong><span>{{ review.stars }} ★ · {{ review.createdAt.slice(0,10).split('-').reverse().join('/') }}</span></div><small>{{ review.courseName }}</small><p>{{ review.content }}</p></article><p v-if="!visibleReviews.length" class="rating-empty">{{ metrics.count?'Không có phản hồi phù hợp.':'Chưa có đánh giá khóa học trong phạm vi đã chọn.' }}</p></div>
    <button v-if="visibleReviews.length>limit" class="rating-link rating-more" @click="limit+=5">Xem thêm phản hồi ({{ visibleReviews.length-limit }})</button>
  </section>
</template>
<script setup lang="ts">
import { computed,ref,watch } from 'vue';
import { Star } from 'lucide-vue-next';
import { summarizeCourseRatings } from '../utils/courseRatingMetrics';
import { courseRatingFixture } from '../mockups/courseRatingFixture';
import type { ReportRow } from '../mockups/reportFixture';
const props=defineProps<{rows:ReportRow[];asOf:string}>();
const onlyLow=ref(false),courseFilter=ref(''),limit=ref(5);
const metrics=computed(()=>summarizeCourseRatings(props.rows.filter(row=>row.status==='Hoàn thành'),courseRatingFixture,props.asOf));
const byCourse=computed(()=>[...new Set(props.rows.map(r=>r.courseName))].map(name=>({name,...summarizeCourseRatings(props.rows.filter(r=>r.courseName===name&&r.status==='Hoàn thành'),courseRatingFixture,props.asOf)})));
const visibleReviews=computed(()=>metrics.value.reviews.filter(r=>(!onlyLow.value||r.stars!<=2)&&(!courseFilter.value||r.courseName===courseFilter.value)));
const learnerName=(id:string)=>props.rows.find(r=>r.learnerId===id)?.name||id;
watch(()=>props.rows,()=>{courseFilter.value='';onlyLow.value=false;limit.value=5;});
watch([onlyLow,courseFilter],()=>{limit.value=5;});
</script>
<style scoped>
.rating-card{margin:18px 0 0;padding:20px;border:1px solid var(--border-color);border-radius:10px;background:var(--bg-card);min-width:0;color:var(--text-main)}header{display:flex;justify-content:space-between;gap:14px}header svg{color:#bc8a23;flex-shrink:0}h3{font-size:15px;margin:0 0 7px}h4{font-size:12px;margin:0}p{color:var(--text-muted);font-size:11px;line-height:1.7;margin:0}.rating-note{color:var(--text-muted);font-size:10px;margin:12px 0}.rating-layout{display:grid;grid-template-columns:160px minmax(0,1fr) minmax(180px,1fr);gap:28px;margin:24px 0}.rating-score>strong{display:block;font-size:42px;font-weight:600;letter-spacing:-1px}.rating-score>strong>small{font-size:17px;color:var(--text-muted);letter-spacing:0}.rating-stars{color:transparent;background-clip:text;-webkit-background-clip:text;font-size:19px;letter-spacing:3px}.rating-score p{margin-top:8px}.rating-distribution{display:grid;gap:10px;align-content:center}.rating-distribution>div{display:flex;gap:12px;align-items:center;font-size:11px;color:var(--text-muted)}.rating-distribution>div>span{width:33px;flex-shrink:0}.rating-track{height:8px;background:var(--bg-subtle);border-radius:4px;flex:1;overflow:hidden}.rating-track i{display:block;height:100%;background:#d9ad4c}.rating-distribution strong{width:20px;text-align:right;color:var(--text-main)}.rating-stats{display:grid;grid-template-columns:1fr 1fr;gap:12px}.rating-stats>div,.rating-stats>button{padding:13px;border:1px solid var(--border-color);border-radius:7px;background:var(--bg-subtle);display:flex;flex-direction:column;align-items:flex-start;gap:7px;text-align:left;color:var(--text-muted);font:inherit;font-size:10px}.rating-stats strong{font-size:25px;color:var(--text-main)}.rating-stats small{font-size:9px;line-height:1.6}.rating-stats>button{cursor:pointer}.rating-stats>button[aria-pressed=true]{border-color:var(--danger-ink)}.rating-subheading{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:20px 0 12px}.rating-subheading>span,.rating-scope{font-size:10px;color:var(--text-muted)}.rating-table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:11px}th{text-align:left;color:var(--text-muted);background:var(--bg-subtle);font-weight:500}th,td{padding:11px;border-bottom:1px solid var(--border-color)}.rating-link{font:inherit;font-size:11px;font-weight:600;color:var(--primary-ink);border:0;background:transparent;cursor:pointer;padding:5px 0;white-space:nowrap}.rating-comments{display:grid;grid-template-columns:1fr 1fr;gap:12px}.rating-comments article{border:1px solid var(--border-color);border-radius:7px;padding:14px;min-width:0}.rating-comments article>div{display:flex;justify-content:space-between;gap:10px;font-size:11px}.rating-comments article>div>span{color:var(--text-muted);white-space:nowrap;font-size:10px}.rating-comments article>small{display:block;font-size:10px;color:var(--text-muted);margin:7px 0}.rating-empty{padding:15px 0}.rating-more{margin-top:12px}button:focus-visible,.rating-table-scroll:focus-visible{outline:2px solid var(--primary-ink);outline-offset:3px}@media(max-width:1100px){.rating-layout{grid-template-columns:130px minmax(0,1fr)}.rating-stats{grid-column:1/-1}}@media(max-width:650px){.rating-card{padding:16px}.rating-layout{gap:16px;grid-template-columns:100px minmax(0,1fr)}.rating-comments{grid-template-columns:1fr}.rating-subheading{align-items:flex-start;flex-wrap:wrap}.rating-score>strong{font-size:35px}.rating-score p{font-size:10px}.rating-comments article>div{flex-wrap:wrap}}@media print{.rating-card{break-inside:auto}.rating-layout{break-inside:avoid}.rating-link{display:none}.rating-table-scroll{overflow:visible}table{white-space:normal}.rating-comments article{break-inside:avoid}}
</style>


